# ==========================================================================
# LOCAL DEVELOPMENT WEB SERVER
# A lightweight PowerShell HTTP server to serve the GitHub Clone locally.
# ==========================================================================

$port = 8000
$localIp = "127.0.0.1"
$listener = New-Object System.Net.HttpListener
$listener.Prefixes.Add("http://$($localIp):$($port)/")

# Handle script interruption (Ctrl+C)
$Host.UI.RawUI.FlushInputBuffer()

try {
    $listener.Start()
    Write-Host "--------------------------------------------------------" -ForegroundColor Cyan
    Write-Host "GitHub Clone server running at: http://$($localIp):$($port)/" -ForegroundColor Green
    Write-Host "To view the bundled version, go to: http://$($localIp):$($port)/dist/" -ForegroundColor Green
    Write-Host "Press Ctrl+C in this terminal window to stop the server." -ForegroundColor Yellow
    Write-Host "--------------------------------------------------------" -ForegroundColor Cyan

    while ($listener.IsListening) {
        $context = $listener.GetContext()
        $request = $context.Request
        $response = $context.Response

        $rawUrl = $request.RawUrl
        # Default document
        if ($rawUrl -eq "/" -or $rawUrl -eq "" -or $rawUrl -eq "/dist" -or $rawUrl -eq "/dist/") {
            if ($rawUrl.StartsWith("/dist")) {
                $rawUrl = "/dist/index.html"
            } else {
                $rawUrl = "/index.html"
            }
        }

        # Remove query string if any
        if ($rawUrl.Contains("?")) {
            $rawUrl = $rawUrl.Substring(0, $rawUrl.IndexOf("?"))
        }

        # Normalize and construct filepath
        $urlPath = $rawUrl.Replace("/", "\").TrimStart("\")
        $filePath = Join-Path $PSScriptRoot $urlPath

        if (Test-Path $filePath -PathType Leaf) {
            # Determine MIME type
            $ext = [System.IO.Path]::GetExtension($filePath).ToLower()
            $mimeType = switch ($ext) {
                ".html" { "text/html; charset=utf-8" }
                ".htm" { "text/html; charset=utf-8" }
                ".css" { "text/css; charset=utf-8" }
                ".js" { "application/javascript; charset=utf-8" }
                ".mjs" { "application/javascript; charset=utf-8" }
                ".json" { "application/json; charset=utf-8" }
                ".png" { "image/png" }
                ".jpg" { "image/jpeg" }
                ".jpeg" { "image/jpeg" }
                ".gif" { "image/gif" }
                ".svg" { "image/svg+xml" }
                ".ico" { "image/x-icon" }
                default { "application/octet-stream" }
            }

            # CORS headers
            $response.Headers.Add("Access-Control-Allow-Origin", "*")
            $response.Headers.Add("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
            $response.ContentType = $mimeType

            # Read file bytes
            $bytes = [System.IO.File]::ReadAllBytes($filePath)
            $response.ContentLength64 = $bytes.Length
            $response.OutputStream.Write($bytes, 0, $bytes.Length)
        } else {
            # 404 Not Found
            $response.StatusCode = 404
            $errMessage = "404 Not Found: $rawUrl"
            $bytes = [System.Text.Encoding]::UTF8.GetBytes($errMessage)
            $response.ContentLength64 = $bytes.Length
            $response.OutputStream.Write($bytes, 0, $bytes.Length)
        }
        $response.OutputStream.Close()
    }
} catch {
    Write-Host "Error: $($_.Exception.Message)" -ForegroundColor Red
} finally {
    if ($listener.IsListening) {
        $listener.Stop()
    }
    $listener.Close()
    Write-Host "Server stopped." -ForegroundColor Yellow
}

