.tooltip-container {
  position: relative;
}

/* ==========================================================================
   GITHUB DASHBOARD & THREE COLUMN LAYOUT
   ========================================================================== */

/* Full width repo pages */
.main-container.repo-mode {
  grid-template-columns: 1fr;
}
.main-container.repo-mode .sidebar {
  display: none !important;
}

/* Dashboard Sidebar overrides */
.sidebar {
  border-right: 1px solid var(--border-color);
  background-color: var(--bg-primary);
  display: flex;
  flex-direction: column;
  padding: 1.5rem 1rem;
}

/* Repositories search list (left column) */
.dashboard-repos-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.75rem;
}
.dashboard-repos-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
}
.repo-search-input {
  width: 100%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 6px 12px;
  font-size: 0.8125rem;
  color: var(--text-primary);
  margin-bottom: 1rem;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.repo-search-input:focus {
  outline: none;
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 3px rgba(88, 166, 255, 0.3);
}
.dashboard-repo-link-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 0.5rem;
  margin: 0.125rem 0;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s;
}
.dashboard-repo-link-item:hover {
  background-color: var(--bg-tertiary);
}
.dashboard-repo-avatar {
  width: 20px;
  height: 20px;
  border-radius: 4px;
  object-fit: cover;
}
.dashboard-repo-name-text {
  font-size: 0.8125rem;
  color: var(--text-primary);
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
}

/* Three Column Dashboard Layout */
.dashboard-grid {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 1.5rem;
  padding: 0;
  max-width: 100%;
}
@media (max-width: 1100px) {
  .dashboard-grid {
    grid-template-columns: 1fr;
  }
}

/* Copilot Chat Assistant styling */
.copilot-card {
  border: 1px solid var(--border-color);
  border-radius: 12px;
  background-color: var(--bg-card);
  padding: 1.25rem;
  margin-bottom: 1.5rem;
  box-shadow: var(--shadow-sm);
  position: relative;
  overflow: hidden;
}
.copilot-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, #bc8cff, #58a6ff, #3fb950);
}
.copilot-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
  font-size: 0.875rem;
  font-weight: 600;
}
.copilot-chat-history {
  max-height: 280px;
  overflow-y: auto;
  margin-bottom: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding-right: 0.25rem;
}
.copilot-chat-bubble {
  display: flex;
  flex-direction: column;
  padding: 0.75rem;
  border-radius: 8px;
  font-size: 0.8125rem;
  line-height: 1.4;
  max-width: 85%;
}
.copilot-chat-bubble.user {
  background-color: rgba(56, 139, 253, 0.1);
  border: 1px solid rgba(56, 139, 253, 0.3);
  align-self: flex-end;
}
.copilot-chat-bubble.ai {
  background-color: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  align-self: flex-start;
}
.copilot-chat-bubble code {
  font-family: var(--font-mono);
  background: var(--bg-primary);
  padding: 2px 4px;
  border-radius: 4px;
  font-size: 0.75rem;
}
.copilot-chat-bubble pre {
  margin-top: 0.5rem;
  background: var(--bg-primary);
  padding: 0.5rem;
  border-radius: 6px;
  overflow-x: auto;
  border: 1px solid var(--border-color);
}
.copilot-chat-bubble pre code {
  padding: 0;
  background: transparent;
}
.copilot-input-area {
  display: flex;
  border: 1px solid var(--border-color);
  background-color: var(--bg-primary);
  border-radius: 8px;
  overflow: hidden;
}
.copilot-textarea {
  flex-grow: 1;
  background: transparent;
  border: none;
  padding: 10px 12px;
  font-size: 0.8125rem;
  color: var(--text-primary);
  resize: none;
  height: 44px;
}
.copilot-textarea:focus {
  outline: none;
}
.copilot-send-btn {
  background: transparent;
  border: none;
  padding: 0 12px;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.2s;
}
.copilot-send-btn:hover {
  color: var(--accent-blue);
}
.copilot-quick-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.75rem;
}
.quick-action-tag {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  padding: 4px 10px;
  border-radius: 100px;
  font-size: 0.75rem;
  color: var(--text-secondary);
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s, color 0.2s;
}
.quick-action-tag:hover {
  background: rgba(88, 166, 255, 0.1);
  border-color: rgba(88, 166, 255, 0.3);
  color: var(--accent-blue);
}

/* Feed section styling */
.feed-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 1.5rem 0 1rem 0;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 0.5rem;
}
.feed-title {
  font-size: 0.95rem;
  font-weight: 600;
}
.feed-item-card {
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--bg-card);
  padding: 1rem;
  margin-bottom: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  box-shadow: var(--shadow-sm);
}
.feed-item-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}
.feed-item-repo-link {
  font-size: 0.875rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 0.375rem;
}
.feed-item-description {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.4;
}
.feed-item-footer {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}
.lang-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  vertical-align: middle;
  margin-right: 0.25rem;
}

/* Right Column Widgets */
.universe-card {
  border: 1px solid var(--border-color);
  border-radius: 12px;
  background: linear-gradient(180deg, #161b22, #0d1117);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  margin-bottom: 1.5rem;
}
.universe-banner {
  background: linear-gradient(135deg, #8a2be2, #4169e1, #ff1493);
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-weight: 800;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-shadow: 0 4px 10px rgba(0,0,0,0.5);
  font-family: var(--font-sans);
}
.universe-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.universe-title {
  font-size: 0.8125rem;
  color: var(--accent-orange);
  font-weight: 700;
}
.universe-desc {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.4;
}
.universe-btn {
  background: #24292e;
  border: 1px solid #444d56;
  color: #fff;
  padding: 8px 16px;
  border-radius: 6px;
  text-align: center;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s;
  margin-top: 0.5rem;
}
.universe-btn:hover {
  background: #2f363d;
  border-color: #586069;
  text-decoration: none;
}

/* Typing indicator dots */
.typing-indicator {
  display: flex;
  gap: 4px;
  align-items: center;
  padding: 4px 0;
}
.typing-dot {
  width: 6px;
  height: 6px;
  background: var(--text-muted);
  border-radius: 50%;
  animation: typing-bounce 1.4s infinite ease-in-out both;
}
.typing-dot:nth-child(1) { animation-delay: -0.32s; }
.typing-dot:nth-child(2) { animation-delay: -0.16s; }

@keyframes typing-bounce {
  0%, 80%, 100% { transform: scale(0); }
  40% { transform: scale(1.0); }
}

