// ==========================================================================
// NAVIGATION COMPONENT - GITHUB ANTIGRAVITY EDITION
// ==========================================================================

export function renderNavigation(state, actions) {
  return `
    <nav class="navbar" style="display: flex; align-items: center; justify-content: space-between; padding: 0.5rem 1rem; border-bottom: 1px solid var(--border-color); background-color: var(--bg-secondary); height: 48px;">
      <div class="nav-left" style="display: flex; align-items: center; gap: 0.75rem;">
        <button class="nav-badge-btn" title="Navigation menu" style="background: transparent; border: none; color: var(--text-primary); cursor: pointer; display: flex; align-items: center;">
          <i data-lucide="menu" style="width: 18px; height: 18px;"></i>
        </button>
        <div class="nav-logo" id="nav-logo-btn" style="cursor: pointer; display: flex; align-items: center; color: var(--text-primary);">
          <i data-lucide="github" style="width: 24px; height: 24px;"></i>
        </div>
        <span class="nav-title" id="nav-dashboard-title" style="cursor: pointer; font-weight: 600; font-size: 0.875rem; color: var(--text-primary);">Dashboard</span>
      </div>

      <div class="nav-center" style="flex-grow: 1; max-width: 320px; margin: 0 1.5rem; position: relative;">
        <div class="search-container" style="width: 100%; display: flex; align-items: center; position: relative;">
          <i data-lucide="search" style="position: absolute; left: 10px; top: 50%; transform: translateY(-50%); width: 14px; height: 14px; color: var(--text-muted); pointer-events: none;"></i>
          <input 
            type="text" 
            class="search-input" 
            placeholder="Type / to search" 
            id="nav-search-input"
            value="${state.searchQuery || ''}"
            style="width: 100%; padding: 4px 12px 4px 32px; font-size: 0.8125rem; height: 28px; background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; color: var(--text-primary);"
          />
        </div>
      </div>

      <div class="nav-right" style="display: flex; align-items: center; gap: 0.5rem;">
        <button class="nav-badge-btn" title="Notifications" style="position: relative; background: transparent; border: none; color: var(--text-primary); cursor: pointer; padding: 4px;">
          <i data-lucide="bell" style="width: 16px; height: 16px;"></i>
          <span class="badge-dot" style="position: absolute; top: 4px; right: 4px; width: 6px; height: 6px; background-color: var(--accent-blue); border-radius: 50%;"></span>
        </button>

        <button class="nav-badge-btn" id="header-create-repo-btn" title="Create new repository" style="background: transparent; border: none; color: var(--text-primary); cursor: pointer; padding: 4px;">
          <i data-lucide="plus" style="width: 16px; height: 16px;"></i>
        </button>

        <button class="nav-badge-btn" title="Issues" id="nav-issues-btn" style="background: transparent; border: none; color: var(--text-primary); cursor: pointer; padding: 4px;">
          <i data-lucide="circle-dot" style="width: 16px; height: 16px;"></i>
        </button>

        <button class="nav-badge-btn" title="Pull Requests" id="nav-pulls-btn" style="background: transparent; border: none; color: var(--text-primary); cursor: pointer; padding: 4px;">
          <i data-lucide="git-pull-request" style="width: 16px; height: 16px;"></i>
        </button>

        <button class="nav-badge-btn" title="Discussions" style="background: transparent; border: none; color: var(--text-primary); cursor: pointer; padding: 4px;">
          <i data-lucide="message-square" style="width: 16px; height: 16px;"></i>
        </button>

        <button class="nav-badge-btn" title="Inbox" style="background: transparent; border: none; color: var(--text-primary); cursor: pointer; padding: 4px;">
          <i data-lucide="inbox" style="width: 16px; height: 16px;"></i>
        </button>

        <div class="nav-profile" id="nav-profile-btn" style="cursor: pointer; margin-left: 0.5rem; display: flex; align-items: center;">
          <img src="${state.user.avatarUrl}" alt="${state.user.name}" class="avatar" style="width: 24px; height: 24px; border-radius: 50%; border: 1px solid var(--border-color);" />
        </div>
      </div>
    </nav>
  `;
}

export function attachNavigationListeners(state, actions) {
  const logo = document.getElementById("nav-logo-btn");
  if (logo) {
    logo.addEventListener("click", () => {
      actions.navigateToDashboard();
    });
  }

  const dashTitle = document.getElementById("nav-dashboard-title");
  if (dashTitle) {
    dashTitle.addEventListener("click", () => {
      actions.navigateToDashboard();
    });
  }

  const profileBtn = document.getElementById("nav-profile-btn");
  if (profileBtn) {
    profileBtn.addEventListener("click", () => {
      actions.navigateToDashboard();
    });
  }

  const plusBtn = document.getElementById("header-create-repo-btn");
  if (plusBtn) {
    plusBtn.addEventListener("click", () => {
      actions.toggleCreateRepoModal(true);
    });
  }

  const searchInput = document.getElementById("nav-search-input");
  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      actions.setSearchQuery(e.target.value);
    });
    searchInput.addEventListener("focus", () => {
      const val = searchInput.value;
      searchInput.value = '';
      searchInput.value = val;
    });
  }
}

