export function renderSidebar(state, actions) {
  const defaultOwnerAvatar = "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=150&auto=format&fit=crop&q=80";
  const secondOwnerAvatar = "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80";

  const repoItems = state.repos.map(repo => {
    const owner = repo.owner || state.user.username;
    const avatar = owner === "theankittsaini" ? secondOwnerAvatar : defaultOwnerAvatar;
    const repoFullName = `${owner}/${repo.name}`;

    return `
      <div class="dashboard-repo-link-item" data-id="${repo.id}" data-name="${repoFullName}">
        <img src="${avatar}" class="dashboard-repo-avatar" alt="${owner}" />
        <span class="dashboard-repo-name-text">${repoFullName}</span>
      </div>
    `;
  }).join('');

  return `
    <aside class="sidebar" style="width: 280px; flex-shrink: 0;">
      <div class="dashboard-repos-header">
        <span class="dashboard-repos-title">Top repositories</span>
        <button class="btn" id="sidebar-new-repo-btn" style="background-color: var(--accent-green); border: 1px solid rgba(240,246,252,0.1); color: #fff; display: flex; align-items: center; gap: 0.35rem; font-size: 0.75rem; padding: 4px 10px; border-radius: 6px; font-weight: 600; cursor: pointer; transition: background-color 0.2s;">
          <i data-lucide="book-marked" style="width: 14px; height: 14px;"></i>
          New
        </button>
      </div>

      <input 
        type="text" 
        class="repo-search-input" 
        id="sidebar-repo-search" 
        placeholder="Find a repository..." 
      />

      <div class="dashboard-repo-list" style="display: flex; flex-direction: column; overflow-y: auto; max-height: calc(100vh - 180px);">
        ${repoItems || '<div style="font-size: 0.75rem; color: var(--text-muted); padding: 0.5rem;">No repositories found.</div>'}
      </div>

      <div style="margin-top: 1rem; border-top: 1px solid var(--border-color); padding-top: 0.75rem;">
        <button class="btn btn-sm" style="background: transparent; border: none; color: var(--text-secondary); cursor: pointer; text-align: left; font-size: 0.75rem; display: flex; align-items: center; gap: 0.25rem;">
          Show more
        </button>
      </div>
    </aside>
  `;
}

export function attachSidebarListeners(state, actions) {
  const newRepoBtn = document.getElementById("sidebar-new-repo-btn");
  if (newRepoBtn) {
    newRepoBtn.addEventListener("click", () => {
      actions.toggleCreateRepoModal(true);
    });
  }

  const repoLinks = document.querySelectorAll(".dashboard-repo-link-item");
  repoLinks.forEach(item => {
    item.addEventListener("click", () => {
      const repoId = item.getAttribute("data-id");
      actions.navigateToRepo(repoId);
    });
  });

  const searchInput = document.getElementById("sidebar-repo-search");
  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      const query = e.target.value.toLowerCase().trim();
      repoLinks.forEach(item => {
        const repoName = item.getAttribute("data-name").toLowerCase();
        if (repoName.includes(query)) {
          item.style.display = "flex";
        } else {
          item.style.display = "none";
        }
      });
    });
  }
}

