// ==========================================================================
// DASHBOARD COMPONENT - GITHUB ANTIGRAVITY EDITION
// ==========================================================================

export function renderDashboard(state, actions) {
  // Center Column: Copilot + Feed
  const copilotHtml = renderCopilotChat();
  const feedHtml = renderHomeFeed();

  // Right Column: Announcements
  const rightSidebarHtml = renderRightSidebar();

  return `
    <div class="dashboard-grid">
      <!-- Center Home Content (Feed & Copilot) -->
      <div class="dashboard-center">
        <h2 style="font-size: 1.25rem; font-weight: 600; margin-bottom: 1.25rem;">Home</h2>
        ${copilotHtml}
        ${feedHtml}
      </div>

      <!-- Right Announcements Sidebar -->
      <div class="dashboard-right">
        ${rightSidebarHtml}
      </div>
    </div>
  `;
}

function renderCopilotChat() {
  return `
    <div class="copilot-card">
      <div class="copilot-header">
        <i data-lucide="sparkles" style="color: var(--accent-purple); width: 18px; height: 18px;"></i>
        <span>Copilot Assistant</span>
      </div>

      <!-- Chat history window -->
      <div class="copilot-chat-history" id="copilot-chat-history">
        <div class="copilot-chat-bubble ai">
          Hi! I am Copilot, your AI developer assistant. Ask me anything, or click one of the quick actions below to see me in action!
        </div>
      </div>

      <!-- Text input container -->
      <div class="copilot-input-area">
        <textarea 
          class="copilot-textarea" 
          id="copilot-chat-input" 
          placeholder="Ask anything or type @ to add context"
          rows="1"
        ></textarea>
        <button class="copilot-send-btn" id="copilot-send-btn" title="Send message">
          <i data-lucide="arrow-right-to-line" style="width: 16px; height: 16px;"></i>
        </button>
      </div>

      <!-- Quick Action tags -->
      <div class="copilot-quick-actions">
        <span class="quick-action-tag" data-action="agent"><i data-lucide="bot" style="width: 12px; height: 12px; display: inline-block; vertical-align: middle; margin-right: 0.25rem;"></i>Agent</span>
        <span class="quick-action-tag" data-action="issue"><i data-lucide="circle-dot" style="width: 12px; height: 12px; display: inline-block; vertical-align: middle; margin-right: 0.25rem;"></i>Create issue</span>
        <span class="quick-action-tag" data-action="code"><i data-lucide="code" style="width: 12px; height: 12px; display: inline-block; vertical-align: middle; margin-right: 0.25rem;"></i>Write code</span>
        <span class="quick-action-tag" data-action="git"><i data-lucide="git-branch" style="width: 12px; height: 12px; display: inline-block; vertical-align: middle; margin-right: 0.25rem;"></i>Git</span>
        <span class="quick-action-tag" data-action="pr"><i data-lucide="git-pull-request" style="width: 12px; height: 12px; display: inline-block; vertical-align: middle; margin-right: 0.25rem;"></i>Pull requests</span>
      </div>
    </div>
  `;
}

function renderHomeFeed() {
  return `
    <div class="feed-header">
      <span class="feed-title">Feed</span>
      <button class="btn btn-sm" id="feed-filter-btn" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); padding: 4px 10px; border-radius: 6px; font-size: 0.75rem; display: flex; align-items: center; gap: 0.25rem; cursor: pointer;">
        <i data-lucide="filter" style="width: 12px; height: 12px;"></i>
        Filter
      </button>
    </div>

    <!-- Feed Items -->
    <div class="feed-item-card">
      <div class="feed-item-header">
        <a href="https://github.com/OpenCut-app/OpenCut" target="_blank" class="feed-item-repo-link">
          <i data-lucide="book-marked" style="color: var(--text-secondary); width: 16px; height: 16px;"></i>
          <span>OpenCut-app/OpenCut</span>
        </a>
        <button class="btn btn-sm" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); font-size: 0.75rem; padding: 3px 8px; border-radius: 6px; cursor: pointer; display: flex; align-items: center; gap: 0.25rem;">
          <i data-lucide="star" style="width: 12px; height: 12px; color: var(--accent-orange);"></i>
          Star
        </button>
      </div>
      <p class="feed-item-description">The open-source CapCut alternative. Built for speed, security, and native multi-track desktop timeline video editing.</p>
      <div class="feed-item-footer">
        <span><span class="lang-dot" style="background-color: #3178c6;"></span>TypeScript</span>
        <span><i data-lucide="star" style="width: 12px; height: 12px; display: inline-block; vertical-align: text-bottom;"></i> 72.5k</span>
        <span>Updated Jul 16</span>
      </div>
    </div>

    <div class="feed-item-card">
      <div class="feed-item-header">
        <a href="https://github.com/Nutlope/hallmark" target="_blank" class="feed-item-repo-link">
          <i data-lucide="book-marked" style="color: var(--text-secondary); width: 16px; height: 16px;"></i>
          <span>Nutlope/hallmark</span>
        </a>
        <button class="btn btn-sm" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); font-size: 0.75rem; padding: 3px 8px; border-radius: 6px; cursor: pointer; display: flex; align-items: center; gap: 0.25rem;">
          <i data-lucide="star" style="width: 12px; height: 12px; color: var(--accent-orange);"></i>
          Star
        </button>
      </div>
      <p class="feed-item-description">Anti-AI-slop design skill library for Claude Code, Cursor, and Codex. Renders sleek interfaces instantly.</p>
