// Basic markdown/code block renderer for mock AI responses
function formatMarkdown(text) {
  let html = text;

  // Code blocks: ```js ... ```
  html = html.replace(/```(javascript|js|python|bash)\n([\s\S]*?)\n```/g, '<pre><code>$2</code></pre>');

  // Inline code: `code`
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');

  // Bold text: **bold**
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

  return html;
}

