// ==========================================================================
// REPOSITORY HEADER COMPONENT - GITHUB ANTIGRAVITY EDITION
// ==========================================================================

export function renderRepoHeader(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return '';

  const owner = repo.owner || state.user.username;
  const openIssuesCount = repo.issues ? repo.issues.filter(i => i.status === "open").length : 0;
  const openPrsCount = repo.pullRequests ? repo.pullRequests.filter(p => p.status === "open").length : 0;

  const tabs = [
    { id: 'code', label: 'Code', icon: 'code' },
    { id: 'issues', label: 'Issues', icon: 'circle-dot', count: openIssuesCount },
    { id: 'pulls', label: 'Pull requests', icon: 'git-pull-request', count: openPrsCount },
    { id: 'agents', label: 'Agents', icon: 'bot' },
    { id: 'actions', label: 'Actions', icon: 'play' },
    { id: 'projects', label: 'Projects', icon: 'table' },
    { id: 'wiki', label: 'Wiki', icon: 'book-open' },
    { id: 'security', label: 'Security and quality', icon: 'shield' },
    { id: 'insights', label: 'Insights', icon: 'bar-chart' },
    { id: 'settings', label: 'Settings', icon: 'settings' }
  ];

  const tabHtml = tabs.map(tab => {
    const isActive = state.activeRepoTab === tab.id;
    const hasCount = tab.count !== undefined && tab.count > 0;

    return `
      <div class="repo-tab ${isActive ? 'active' : ''}" data-tab="${tab.id}" style="cursor: pointer; display: flex; align-items: center; gap: 0.35rem; padding: 0.5rem 0.75rem; border-bottom: 2px solid ${isActive ? 'var(--accent-orange)' : 'transparent'}; color: ${isActive ? 'var(--text-primary)' : 'var(--text-secondary)'}; font-size: 0.8125rem; font-weight: ${isActive ? '600' : '400'}; transition: color 0.2s;">
        <i data-lucide="${tab.icon}" style="width: 14px; height: 14px;"></i>
        <span>${tab.label}</span>
        ${hasCount ? `<span class="repo-tab-count" style="background: rgba(255,255,255,0.08); padding: 1px 5px; border-radius: 10px; font-size: 0.7rem; margin-left: 0.25rem;">${tab.count}</span>` : ''}
      </div>
    `;
  }).join('');

  return `
    <div class="repo-detail-header" style="border-bottom: 1px solid var(--border-color); background-color: var(--bg-secondary); padding: 1rem 1.5rem 0 1.5rem;">
      <div class="repo-detail-title-line" style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem;">
        <div class="repo-detail-path" style="display: flex; align-items: center; gap: 0.35rem; font-size: 1.15rem; font-weight: 400; color: var(--text-primary);">
          <span class="owner" style="color: var(--accent-blue); font-weight: 500;">${owner}</span>
          <span class="separator" style="color: var(--text-muted);">/</span>
          <span class="name" id="repo-header-name" style="font-weight: 600; display: flex; align-items: center; gap: 0.25rem;">
            ${repo.name}
            <i data-lucide="chevron-down" style="width: 12px; height: 12px; color: var(--text-muted); cursor: pointer;"></i>
          </span>
          <span class="badge" style="margin-left: 0.5rem; font-size: 0.7rem; padding: 1px 6px; border: 1px solid var(--border-color); border-radius: 12px; color: var(--text-secondary); font-weight: 500;">
            ${repo.isPrivate ? 'Private' : 'Public'}
          </span>
        </div>

        <div class="repo-detail-actions" style="display: flex; gap: 0.5rem; align-items: center;">
          <button class="btn btn-sm" style="display: flex; align-items: center; gap: 0.25rem; background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 4px 10px; font-size: 0.75rem; color: var(--text-primary); cursor: pointer; font-weight: 500;">
            <i data-lucide="pin" style="width: 14px; height: 14px;"></i>
            <span>Pin</span>
          </button>

          <button class="btn btn-sm" style="display: flex; align-items: center; gap: 0.25rem; background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 4px 10px; font-size: 0.75rem; color: var(--text-primary); cursor: pointer; font-weight: 500;">
            <i data-lucide="eye" style="width: 14px; height: 14px;"></i>
            <span>Watch</span>
            <span style="background: rgba(255,255,255,0.08); padding: 1px 5px; border-radius: 10px; font-size: 0.7rem; margin-left: 0.25rem;">0</span>
            <i data-lucide="chevron-down" style="width: 10px; height: 10px; color: var(--text-secondary); margin-left: 0.15rem;"></i>
          </button>

          <button class="btn btn-sm" id="repo-header-fork-btn" style="display: flex; align-items: center; gap: 0.25rem; background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 4px 10px; font-size: 0.75rem; color: var(--text-primary); cursor: pointer; font-weight: 500;">
            <i data-lucide="git-fork" style="width: 14px; height: 14px;"></i>
            <span>Fork</span>
            <span style="background: rgba(255,255,255,0.08); padding: 1px 5px; border-radius: 10px; font-size: 0.7rem; margin-left: 0.25rem;">${repo.forks || 0}</span>
            <i data-lucide="chevron-down" style="width: 10px; height: 10px; color: var(--text-secondary); margin-left: 0.15rem;"></i>
          </button>

          <button class="btn btn-sm star-btn" data-id="${repo.id}" style="display: flex; align-items: center; gap: 0.25rem; background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 4px 10px; font-size: 0.75rem; color: var(--text-primary); cursor: pointer; font-weight: 500;">
            <i data-lucide="star" style="width: 14px; height: 14px; color: var(--accent-orange);"></i>
            <span>Star</span>
            <span style="background: rgba(255,255,255,0.08); padding: 1px 5px; border-radius: 10px; font-size: 0.7rem; margin-left: 0.25rem;">${repo.stars || 0}</span>
            <i data-lucide="chevron-down" style="width: 10px; height: 10px; color: var(--text-secondary); margin-left: 0.15rem;"></i>
          </button>
        </div>
      </div>

      <div class="repo-tabs" style="display: flex; gap: 0.5rem; overflow-x: auto;">
        ${tabHtml}
      </div>
    </div>
  `;
}

export function attachRepoHeaderListeners(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return;

  // Star button
  const starBtn = document.querySelector(".repo-detail-header .star-btn");
  if (starBtn) {
    starBtn.addEventListener("click", () => {
      actions.starRepository(repo.id);
    });
  }

  // Fork button
  const forkBtn = document.getElementById("repo-header-fork-btn");
  if (forkBtn) {
    forkBtn.addEventListener("click", () => {
      actions.forkRepository(repo.id);
    });
  }

  // Tabs clicks
  const tabs = document.querySelectorAll(".repo-tab");
  tabs.forEach(tab => {
    tab.addEventListener("click", () => {
      const tabId = tab.getAttribute("data-tab");
      actions.switchTab(tabId);
    });
  });
}

