// ==========================================================================
// FILE EXPLORER & CODE VIEW COMPONENT - GITHUB ANTIGRAVITY EDITION
// ==========================================================================

export function renderFileExplorer(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return '';

  const activeFilePath = state.activeFilePath;

  // IF NO FILE IS SELECTED, RENDER THE REPOSITORY LANDING PAGE
  if (activeFilePath === null) {
    return renderLandingPage(state, repo, actions);
  }

  // OTHERWISE, RENDER THE TRADITIONAL FILE VIEWER PANE
  return renderFileViewerPane(state, repo, actions);
}

// --------------------------------------------------------------------------
// 1. REPOSITORY LANDING PAGE VIEW RENDERER
// --------------------------------------------------------------------------
function renderLandingPage(state, repo, actions) {
  const currentFolder = state.activeFolderPath || '';
  const owner = repo.owner || state.user.username;
  const avatar = owner === "theankittsaini" 
    ? "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80" 
    : "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=150&auto=format&fit=crop&q=80";

  // Resolve files and folders at the current directory depth
  const items = [];
  const foldersSeen = new Set();

  repo.files.forEach(file => {
    let relativePath = file.path;
    if (currentFolder && !relativePath.startsWith(currentFolder + '/')) {
      return;
    }
    if (currentFolder) {
      relativePath = relativePath.substring(currentFolder.length + 1);
    }

    const parts = relativePath.split('/');
    if (parts.length > 1) {
      const folderName = parts[0];
      const fullFolderPath = currentFolder ? `${currentFolder}/${folderName}` : folderName;
      if (!foldersSeen.has(fullFolderPath)) {
        foldersSeen.add(fullFolderPath);
        items.push({
          type: 'folder',
          name: folderName,
          path: fullFolderPath,
          latestCommit: repo.commits[0] || { message: "Initial commit", date: repo.updatedAt }
        });
      }
    } else {
      items.push({
        type: 'file',
        name: parts[0],
        path: file.path,
        latestCommit: repo.commits[0] || { message: "Initial commit", date: repo.updatedAt }
      });
    }
  });

  // Sort folders first, then files alphabetically
  items.sort((a, b) => {
    if (a.type !== b.type) {
      return a.type === 'folder' ? -1 : 1;
    }
    return a.name.localeCompare(b.name);
  });

  // Render breadcrumbs if inside folder
  let breadcrumbHtml = '';
  if (currentFolder) {
    const parts = currentFolder.split('/');
    let accum = '';
    const crumbs = parts.map((part, index) => {
      accum = accum ? `${accum}/${part}` : part;
      return `<span class="breadcrumb-item" data-folder="${accum}" style="color: var(--accent-blue); cursor: pointer; font-weight: 500;">${part}</span>`;
    }).join(' <span style="color: var(--text-muted);">/</span> ');

    breadcrumbHtml = `
      <div class="breadcrumb-navigation" style="margin-bottom: 1rem; font-size: 0.85rem; display: flex; align-items: center; gap: 0.35rem; border-bottom: 1px solid var(--border-color); padding-bottom: 0.5rem;">
        <span class="breadcrumb-item-root" data-folder="" style="color: var(--accent-blue); cursor: pointer; font-weight: 500;">${repo.name}</span>
        <span style="color: var(--text-muted);">/</span>
        ${crumbs}
      </div>
    `;
  }

  // Render table rows
  const tableRows = [];

  // Back link row if inside subfolder
  if (currentFolder) {
    const parts = currentFolder.split('/');
    parts.pop();
    const parentFolder = parts.join('/');
    tableRows.push(`
      <tr class="file-table-row" data-type="parent-folder" data-path="${parentFolder}" style="cursor: pointer; border-bottom: 1px solid var(--border-color); transition: background-color 0.2s;">
        <td style="padding: 8px 12px; display: flex; align-items: center; gap: 0.5rem; font-size: 0.8125rem;">
          <i data-lucide="corner-up-left" style="width: 14px; height: 14px; color: var(--text-muted);"></i>
          <span style="font-weight: 600; color: var(--text-muted);">..</span>
        </td>
        <td style="padding: 8px 12px; font-size: 0.8125rem; color: var(--text-muted);">Go back to parent directory</td>
        <td style="padding: 8px 12px; text-align: right; font-size: 0.8125rem; color: var(--text-muted);">-</td>
      </tr>
    `);
  }

  items.forEach(item => {
    const icon = item.type === 'folder' ? 'folder' : 'file-text';
    const color = item.type === 'folder' ? '#58a6ff' : 'var(--text-secondary)';

    // Convert UTC date to simple relative time
    const dateStr = formatRelativeTime(item.latestCommit.date || repo.updatedAt);
    const shortHash = item.latestCommit.hash ? item.latestCommit.hash.substring(0, 7) : 'de65767';

    tableRows.push(`
      <tr class="file-table-row clickable-item" data-type="${item.type}" data-path="${item.path}" style="cursor: pointer; border-bottom: 1px solid var(--border-color); transition: background-color 0.2s;">
        <td style="padding: 10px 12px; display: flex; align-items: center; gap: 0.5rem; font-size: 0.8125rem; font-weight: ${item.type === 'folder' ? '600' : '400'}; color: ${item.type === 'folder' ? 'var(--text-primary)' : 'var(--text-primary)'}; max-width: 250px; text-overflow: ellipsis; overflow: hidden; white-space: nowrap;">
          <i data-lucide="${icon}" style="width: 14px; height: 14px; color: ${color}; flex-shrink: 0;"></i>
          <span class="file-name-text">${item.name}</span>
        </td>
        <td style="padding: 10px 12px; font-size: 0.8125rem; color: var(--text-secondary); text-overflow: ellipsis; overflow: hidden; white-space: nowrap; max-width: 320px;">
          ${item.latestCommit.message}
        </td>
        <td style="padding: 10px 12px; text-align: right; font-size: 0.8125rem; color: var(--text-muted); white-space: nowrap;">
          ${dateStr}
        </td>
      </tr>
    `);
  });

  // Load README.md if it exists
  const readmeFile = repo.files.find(f => f.path.toLowerCase() === 'readme.md');
  let readmeBlockHtml = '';
  if (readmeFile) {
    readmeBlockHtml = `
      <div class="readme-card-container" style="border: 1px solid var(--border-color); border-radius: 8px; margin-top: 1.5rem; background-color: var(--bg-card); overflow: hidden;">
        <div class="readme-card-header" style="padding: 10px 16px; border-bottom: 1px solid var(--border-color); display: flex; align-items: center; justify-content: space-between; background-color: var(--bg-tertiary);">
          <div style="display: flex; align-items: center; gap: 0.5rem; font-size: 0.8125rem; font-weight: 600; color: var(--text-primary);">
            <i data-lucide="align-left" style="width: 14px; height: 14px;"></i>
            <span>README.md</span>
          </div>
          <i data-lucide="pencil" style="width: 12px; height: 12px; color: var(--text-muted); cursor: pointer;" title="Edit README"></i>
        </div>
        <div class="readme-card-body" style="padding: 1.5rem; font-size: 0.875rem; color: var(--text-primary); line-height: 1.6; font-family: var(--font-sans);">
          ${formatReadme(readmeFile.content)}
        </div>
      </div>
    `;
  }

  // Latest Commit banner
  const latestCommit = repo.commits[0] || { hash: "de65767", message: "Initial commit", date: repo.updatedAt };
  const commitAge = formatRelativeTime(latestCommit.date);
  const commitsCount = repo.commits ? repo.commits.length : 1;

  // RENDER TWO-COLUMN LANDING PAGE
  return `
    <div style="display: grid; grid-template-columns: 1fr 300px; gap: 1.5rem; margin-top: 1rem;">
      <!-- Left side (Files + README) -->
      <div style="display: flex; flex-direction: column;">

        <!-- Action strip -->
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem;">
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <!-- Branch Dropdown -->
            <button class="btn btn-sm" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 4px 10px; font-size: 0.75rem; display: flex; align-items: center; gap: 0.25rem; font-weight: 600; cursor: pointer; color: var(--text-primary);">
              <i data-lucide="git-branch" style="width: 12px; height: 12px;"></i>
              <span>main</span>
              <i data-lucide="chevron-down" style="width: 10px; height: 10px; color: var(--text-secondary); margin-left: 0.15rem;"></i>
            </button>
            <span style="font-size: 0.75rem; color: var(--text-secondary); margin-left: 0.5rem; cursor: pointer;">
              <strong>1</strong> Branch
            </span>
            <span style="font-size: 0.75rem; color: var(--text-secondary); margin-left: 0.25rem; cursor: pointer;">
              <strong>0</strong> Tags
            </span>
          </div>

          <div style="display: flex; gap: 0.5rem; align-items: center;">
            <button class="btn btn-sm" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 4px 10px; font-size: 0.75rem; color: var(--text-primary); cursor: pointer; font-weight: 500;">
              Go to file
            </button>
            <button class="btn btn-sm" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 4px 10px; font-size: 0.75rem; color: var(--text-primary); cursor: pointer; font-weight: 500; display: flex; align-items: center; gap: 0.15rem;">
              Add file
              <i data-lucide="chevron-down" style="width: 10px; height: 10px; color: var(--text-secondary);"></i>
            </button>
            <button class="btn btn-sm" style="background: var(--accent-green); border: 1px solid rgba(240,246,252,0.1); border-radius: 6px; padding: 4px 12px; font-size: 0.75rem; color: #fff; cursor: pointer; font-weight: 600; display: flex; align-items: center; gap: 0.25rem;">
              <i data-lucide="code" style="width: 12px; height: 12px;"></i>
              Code
              <i data-lucide="chevron-down" style="width: 10px; height: 10px; color: rgba(255,255,255,0.7);"></i>
            </button>
          </div>
        </div>

        <!-- Latest Commit Strip -->
        <div style="border: 1px solid var(--border-color); border-radius: 8px 8px 0 0; border-bottom: none; background-color: var(--bg-tertiary); padding: 8px 12px; display: flex; justify-content: space-between; align-items: center;">
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <img src="${avatar}" style="width: 20px; height: 20px; border-radius: 50%; object-fit: cover;" alt="${owner}" />
            <span style="font-size: 0.8125rem; font-weight: 600; color: var(--text-primary); cursor: pointer;">${owner}</span>
            <span style="font-size: 0.8125rem; color: var(--text-secondary); cursor: pointer;" class="latest-commit-msg-link">${latestCommit.message}</span>
          </div>

          <div style="display: flex; align-items: center; gap: 0.75rem; font-size: 0.8125rem;">
            <span style="color: var(--text-muted); cursor: pointer;" title="${latestCommit.date}">
              ${latestCommit.hash ? latestCommit.hash.substring(0,7) : 'de65767'} • ${commitAge}
            </span>
            <span style="font-weight: 600; color: var(--text-primary); display: flex; align-items: center; gap: 0.25rem; cursor: pointer;" class="commits-count-link">
              <i data-lucide="history" style="width: 14px; height: 14px; color: var(--text-secondary);"></i>
              <strong>${commitsCount}</strong> Commits
            </span>
          </div>
        </div>

        <!-- Breadcrumbs path rendering -->
        ${breadcrumbHtml}

        <!-- Files Table -->
        <div style="border: 1px solid var(--border-color); border-radius: 0 0 8px 8px; overflow: hidden; background-color: var(--bg-card);">
          <table style="width: 100%; border-collapse: collapse; text-align: left;">
            <tbody>
              ${tableRows.join('')}
            </tbody>
          </table>
        </div>

        <!-- README Markdown render block -->
        ${readmeBlockHtml}
      </div>

      <!-- Right side (About/Sidebar) -->
      <div style="display: flex; flex-direction: column; gap: 1.5rem; font-family: var(--font-sans);">
        <!-- About Box -->
        <div style="border-bottom: 1px solid var(--border-color); padding-bottom: 1rem;">
          <h3 style="font-size: 0.875rem; font-weight: 600; display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.5rem; color: var(--text-primary);">
            <span>About</span>
            <i data-lucide="settings" style="width: 14px; height: 14px; color: var(--text-muted); cursor: pointer;"></i>
          </h3>
          <p style="font-size: 0.8125rem; color: var(--text-secondary); line-height: 1.4; margin-bottom: 1rem;">
            ${repo.description || 'No description, website, or topics provided.'}
          </p>

          <div style="display: flex; flex-direction: column; gap: 0.5rem; font-size: 0.8125rem; color: var(--text-secondary);">
            <div style="display: flex; align-items: center; gap: 0.5rem; cursor: pointer;">
              <i data-lucide="book-open" style="width: 14px; height: 14px; color: var(--text-muted);"></i>
              <span>Readme</span>
            </div>
            <div style="display: flex; align-items: center; gap: 0.5rem; cursor: pointer;">
              <i data-lucide="activity" style="width: 14px; height: 14px; color: var(--text-muted);"></i>
              <span>Activity</span>
            </div>
            <div style="display: flex; align-items: center; gap: 0.5rem; cursor: pointer;">
              <i data-lucide="star" style="width: 14px; height: 14px; color: var(--text-muted);"></i>
              <span><strong>${repo.stars || 0}</strong> stars</span>
            </div>
            <div style="display: flex; align-items: center; gap: 0.5rem; cursor: pointer;">
              <i data-lucide="eye" style="width: 14px; height: 14px; color: var(--text-muted);"></i>
              <span><strong>0</strong> watching</span>
            </div>
            <div style="display: flex; align-items: center; gap: 0.5rem; cursor: pointer;">
              <i data-lucide="git-fork" style="width: 14px; height: 14px; color: var(--text-muted);"></i>
              <span><strong>${repo.forks || 0}</strong> forks</span>
            </div>
          </div>
        </div>

        <!-- Releases Box -->
        <div style="border-bottom: 1px solid var(--border-color); padding-bottom: 1rem;">
          <h3 style="font-size: 0.875rem; font-weight: 600; margin-bottom: 0.5rem; color: var(--text-primary); cursor: pointer;">
            Releases
          </h3>
          <p style="font-size: 0.75rem; color: var(--text-muted);">
            No releases published.<br/>
            <span style="color: var(--accent-blue); cursor: pointer; text-decoration: none;">Create a new release</span>
          </p>
        </div>

        <!-- Packages Box -->
        <div style="border-bottom: 1px solid var(--border-color); padding-bottom: 1rem;">
          <h3 style="font-size: 0.875rem; font-weight: 600; margin-bottom: 0.5rem; color: var(--text-primary); cursor: pointer;">
            Packages
          </h3>
          <p style="font-size: 0.75rem; color: var(--text-muted);">
            No packages published.<br/>
            <span style="color: var(--accent-blue); cursor: pointer; text-decoration: none;">Publish your first package</span>
          </p>
        </div>

        <!-- Contributors Box -->
        <div>
          <h3 style="font-size: 0.875rem; font-weight: 600; margin-bottom: 0.75rem; color: var(--text-primary); cursor: pointer;">
            Contributors <span style="background: rgba(255,255,255,0.08); padding: 1px 5px; border-radius: 10px; font-size: 0.7rem;">1</span>
          </h3>
          <div style="display: flex; align-items: center; gap: 0.5rem; cursor: pointer;">
            <img src="${avatar}" style="width: 24px; height: 24px; border-radius: 50%; border: 1px solid var(--border-color); object-fit: cover;" alt="${owner}" title="${owner}" />
            <span style="font-size: 0.8125rem; font-weight: 600; color: var(--text-primary);">${owner}</span>
          </div>
        </div>
      </div>
    </div>
  `;
}

// --------------------------------------------------------------------------
// 2. TRADITIONAL CODE EDITOR / VIEWER PANE RENDERER
// --------------------------------------------------------------------------
function renderFileViewerPane(state, repo, actions) {
  const activeFilePath = state.activeFilePath;
  const activeFile = repo.files.find(f => f.path === activeFilePath);

  // Build the hierarchical tree from the flat files list for the sidebar
  const tree = buildFileTree(repo.files);

  // Render tree node HTML recursively
  function renderNode(node, depth = 0) {
    if (node.type === 'file') {
      const isActive = node.path === activeFilePath;
      return `
        <li class="tree-item-container">
          <div class="tree-node ${isActive ? 'active' : ''}" data-type="file" data-path="${node.path}" style="padding-left: ${12 + depth * 12}px;">
            <div class="tree-node-icon file ${isActive ? 'active' : ''}">
              <i data-lucide="file-code"></i>
            </div>
            <span style="font-size: 0.8125rem; color: ${isActive ? 'var(--accent-blue)' : 'var(--text-primary)'};">${node.name}</span>
          </div>
        </li>
      `;
    } else {
      const isExpanded = state.expandedFolders ? state.expandedFolders.includes(node.path) : true;
      const childrenHtml = isExpanded 
        ? `<ul class="tree-sub-list" style="list-style:none; padding:0; margin:0;">${Object.values(node.children).map(child => renderNode(child, depth + 1)).join('')}</ul>`
        : '';

      return `
        <li class="tree-item-container">
          <div class="tree-node folder-node" data-type="folder" data-path="${node.path}" style="padding-left: ${12 + depth * 12}px;">
            <div class="tree-node-icon folder">
              <i data-lucide="${isExpanded ? 'folder-open' : 'folder'}"></i>
            </div>
