            <span style="font-weight: 600;">${activeFile.path}</span>
            <span style="font-size: 0.75rem; color: var(--text-muted); margin-left: 0.5rem;">(${lines.length} lines)</span>
          </div>

          <div class="file-view-actions" style="display: flex; gap: 0.5rem;">
            ${isEditing ? `
              <button class="btn btn-sm btn-primary" id="commit-changes-trigger-btn" style="background: var(--accent-green); border: 1px solid rgba(240,246,252,0.1); color: #fff; padding: 4px 10px; border-radius: 6px; font-size: 0.75rem; font-weight: 600; cursor: pointer;">Commit Changes</button>
              <button class="btn btn-sm" id="cancel-edit-btn" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); color: var(--text-primary); padding: 4px 10px; border-radius: 6px; font-size: 0.75rem; cursor: pointer;">Cancel</button>
            ` : `
              <button class="btn btn-sm" id="edit-file-btn" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); color: var(--text-primary); padding: 4px 10px; border-radius: 6px; font-size: 0.75rem; cursor: pointer; display: flex; align-items: center; gap: 0.25rem;">
                <i data-lucide="edit-3" style="width: 12px; height: 12px;"></i>
                <span>Edit file</span>
              </button>
            `}
          </div>
        </div>

        <div class="file-content-container" style="display: flex; min-height: 380px;">
          ${isEditing ? `
            <div style="display: flex; flex-direction: column; width: 100%;">
              <textarea class="composer-textarea" id="file-editor-textarea" style="flex-grow: 1; font-family: var(--font-mono); font-size: 0.8125rem; padding: 1rem; border: none; background: #07090e; color: #fff; height: 350px; resize: vertical; line-height: 1.5; outline: none;">${activeFile.content}</textarea>

              <!-- Commit form section -->
              <div style="padding: 1.25rem; border-top: 1px solid var(--border-color); background-color: var(--bg-tertiary); display: flex; flex-direction: column; gap: 0.75rem;">
                <h4 style="font-size: 0.85rem; font-weight: 700; color: var(--text-primary);">Commit changes</h4>
                <div class="form-group" style="margin: 0;">
                  <input type="text" class="form-input" id="commit-msg-input" placeholder="Update ${activeFile.path.split('/').pop()}" style="width: 100%; background: var(--bg-primary); border: 1px solid var(--border-color); border-radius: 6px; padding: 6px 12px; font-size: 0.8125rem; color: var(--text-primary);" />
                </div>
                <div class="form-group" style="margin: 0;">
                  <textarea class="form-input" id="commit-desc-input" placeholder="Add an optional extended description..." rows="2" style="width: 100%; background: var(--bg-primary); border: 1px solid var(--border-color); border-radius: 6px; padding: 6px 12px; font-size: 0.8125rem; color: var(--text-primary); resize: vertical;"></textarea>
                </div>
              </div>
            </div>
          ` : `
            <div style="display: flex; width: 100%;">
              <pre class="line-numbers" style="padding: 1rem 0.5rem 1rem 1rem; color: var(--text-muted); font-family: var(--font-mono); font-size: 0.8125rem; text-align: right; user-select: none; border-right: 1px solid var(--border-color); background-color: #07090e; margin: 0;">${lineNumbersHtml}</pre>
              <pre class="code-body" style="flex-grow: 1; padding: 1rem; color: var(--text-primary); font-family: var(--font-mono); font-size: 0.8125rem; overflow-x: auto; background-color: #07090e; margin: 0; line-height: 1.5; white-space: pre;"><code>${highlightedCode}</code></pre>
            </div>
          `}
        </div>
      </div>
    `;
  } else {
    codePaneHtml = `
      <div style="display: flex; align-items: center; justify-content: center; height: 100%; border: 1px dashed var(--border-color); border-radius: 8px; padding: 3rem;">
        <p style="color: var(--text-muted); font-size: 0.8125rem;">Select a file from the sidebar explorer to view its contents.</p>
