  return `
    <div style="margin-top: 1rem; display: flex; gap: 0.5rem; margin-bottom: 0.5rem;">
      <span class="back-to-landing-btn" style="color: var(--accent-blue); font-size: 0.8125rem; cursor: pointer; font-weight: 500; display: flex; align-items: center; gap: 0.25rem;">
        <i data-lucide="arrow-left" style="width: 14px; height: 14px;"></i>
        Back to Repository Home
      </span>
    </div>
    <div class="code-explorer-layout" style="display: grid; grid-template-columns: 260px 1fr; gap: 1rem; align-items: start;">
      <!-- Tree Sidebar -->
      <div class="file-tree-container" style="border: 1px solid var(--border-color); border-radius: 8px; background: var(--bg-card); padding: 0.75rem; max-height: 600px; overflow-y: auto;">
        <h4 style="font-size: 0.75rem; text-transform: uppercase; color: var(--text-muted); letter-spacing: 0.5px; margin-bottom: 0.5rem; font-weight: 700; padding-left: 12px;">Files</h4>
        <ul style="list-style: none; padding: 0; margin: 0;">
          ${treeHtml}
        </ul>
      </div>

      <!-- Right Pane Code Editor -->
      ${codePaneHtml}
    </div>
  `;
}

// --------------------------------------------------------------------------
// HELPER METHODS
// --------------------------------------------------------------------------

// Generates time-ago strings
function formatRelativeTime(dateString) {
  if (!dateString) return "8 months ago";
  const date = new Date(dateString);
  const now = new Date();
  const diffMs = now - date;

  const diffSecs = Math.floor(diffMs / 1000);
  const diffMins = Math.floor(diffSecs / 60);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffSecs < 60) return "just now";
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 30) return `${diffDays}d ago`;

  // Format as date: MMM d, yyyy
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

// Minimal README Markdown formatter
function formatReadme(content) {
  let html = content;
  // HTML escape first
  html = html.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

  // Heading: # Title
  html = html.replace(/^#\s+(.+)$/gm, '<h1 style="font-size: 1.5rem; font-weight: 700; border-bottom: 1px solid var(--border-color); padding-bottom: 0.5rem; margin-top: 1rem; margin-bottom: 0.75rem;">$1</h1>');
  // Heading 2: ## Subtitle
  html = html.replace(/^##\s+(.+)$/gm, '<h2 style="font-size: 1.2rem; font-weight: 600; border-bottom: 1px solid var(--border-color); padding-bottom: 0.35rem; margin-top: 1rem; margin-bottom: 0.5rem;">$1</h2>');
  // Heading 3: ### Minor heading
  html = html.replace(/^###\s+(.+)$/gm, '<h3 style="font-size: 1rem; font-weight: 600; margin-top: 1rem; margin-bottom: 0.5rem;">$1</h3>');

  // Blockquote: > text
  html = html.replace(/^>\s+(.+)$/gm, '<blockquote style="border-left: 4px solid var(--text-muted); color: var(--text-secondary); padding-left: 1rem; margin: 1rem 0;">$1</blockquote>');

  // Code blocks: ```python ... ```
  html = html.replace(/```(python|js|bash|javascript)\n([\s\S]*?)\n```/g, '<pre style="background: var(--bg-primary); padding: 1rem; border-radius: 6px; border: 1px solid var(--border-color); overflow-x: auto; font-family: var(--font-mono); font-size: 0.8125rem; line-height: 1.4; margin: 1rem 0;"><code style="background: transparent; padding: 0;">$2</code></pre>');

  // Bullet items: - **Bold**: text
  html = html.replace(/^\-\s+(.+)$/gm, '<li style="margin-left: 1.5rem; margin-bottom: 0.25rem;">$1</li>');

  // Inline code: `text`
  html = html.replace(/`([^`]+)`/g, '<code style="font-family: var(--font-mono); background: var(--bg-tertiary); padding: 2px 4px; border-radius: 4px; font-size: 0.75rem;">$1</code>');
  // Bold: **text**
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

  // Paragraph matching: replace empty lines with spacing
  html = html.replace(/\n\n/g, '<div style="margin-bottom: 0.75rem;"></div>');

  return html;
}

// Construct nested directories from flat files array
function buildFileTree(files) {
  const root = { name: 'root', type: 'folder', children: {} };

  files.forEach(file => {
    const parts = file.path.split('/');
    let current = root;

    parts.forEach((part, index) => {
      const isLast = index === parts.length - 1;
      const pathSoFar = parts.slice(0, index + 1).join('/');

      if (isLast) {
        current.children[part] = {
          name: part,
          type: 'file',
          path: file.path
        };
      } else {
        if (!current.children[part]) {
          current.children[part] = {
            name: part,
            type: 'folder',
            path: pathSoFar,
            children: {}
          };
        }
        current = current.children[part];
      }
    });
  });

  return root;
}

function getFileExtension(path) {
  if (!path) return '';
  return path.split('.').pop().toLowerCase();
}

// Primitive highlighter
function highlightCode(code, ext) {
  let escaped = escapeHtml(code);

  if (ext === 'js' || ext === 'mjs' || ext === 'json' || ext === 'py') {
    // Keywords
    const keywords = ['const', 'let', 'var', 'function', 'class', 'return', 'import', 'from', 'export', 'default', 'if', 'else', 'for', 'while', 'in', 'def', 'try', 'except', 'class', 'import', 'as', 'from', 'pass', 'with', 'print'];
    keywords.forEach(kw => {
      const re = new RegExp('\\b(' + kw + ')\\b', 'g');
      escaped = escaped.replace(re, '<span style="color: var(--accent-red);">$1</span>');
    });
    // Strings
    escaped = escaped.replace(/(&quot;.*?&quot;|&#039;.*?&#039;|`.*?`)/g, '<span style="color: var(--accent-blue);">$1</span>');
    // Comments
    escaped = escaped.replace(/(\/\/.*|#.*|\/\*[\s\S]*?\*\/)/g, '<span style="color: var(--text-muted);">$1</span>');
    // Numbers
    escaped = escaped.replace(/\b(\d+)\b/g, '<span style="color: var(--accent-orange);">$1</span>');
  } else if (ext === 'css') {
    // Properties
    escaped = escaped.replace(/\b([a-zA-Z\-]+)(?=\s*:)/g, '<span style="color: var(--accent-blue);">$1</span>');
    // Comments
    escaped = escaped.replace(/(\/\*[\s\S]*?\*\/)/g, '<span style="color: var(--text-muted);">$1</span>');
    // Numbers/Units
    escaped = escaped.replace(/\b(\d+px|\d+rem|\d+s|\d+%|\b\d+\b)/g, '<span style="color: var(--accent-orange);">$1</span>');
  } else if (ext === 'html') {
    // Tags
    escaped = escaped.replace(/(&lt;\/?[a-zA-Z0-9]+)(&gt;|\s)/g, '<span style="color: var(--accent-red);">$1</span>$2');
    // Comments
    escaped = escaped.replace(/(&lt;!--[\s\S]*?--&gt;)/g, '<span style="color: var(--text-muted);">$1</span>');
  }

  return escaped;
}

function escapeHtml(text) {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

// --------------------------------------------------------------------------
// 3. ATTACH LISTENERS
// --------------------------------------------------------------------------
export function attachFileExplorerListeners(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return;

  const activeFilePath = state.activeFilePath;

  // IF ON REPOSITORY LANDING PAGE
  if (activeFilePath === null) {
    // Dynamic file explorer links (folders and files)
    const tableRows = document.querySelectorAll(".file-table-row");
    tableRows.forEach(row => {
      row.addEventListener("click", () => {
        const type = row.getAttribute("data-type");
        const path = row.getAttribute("data-path");

        if (type === "folder") {
          actions.navigateToFolder(path);
        } else if (type === "parent-folder") {
          actions.navigateToFolder(path);
        } else if (type === "file") {
          actions.selectFile(path);
        }
      });
    });

    // Breadcrumbs folder links
    const breadcrumbs = document.querySelectorAll(".breadcrumb-navigation .breadcrumb-item, .breadcrumb-navigation .breadcrumb-item-root");
    breadcrumbs.forEach(crumb => {
      crumb.addEventListener("click", () => {
        const path = crumb.getAttribute("data-folder");
        actions.navigateToFolder(path);
      });
    });

    // Commits link click redirect to Commits tab
    const commitsCountLink = document.querySelector(".commits-count-link");
    if (commitsCountLink) {
      commitsCountLink.addEventListener("click", () => {
        actions.switchTab("commits");
      });
    }

    // Latest commit link click redirect to Commits tab
    const latestCommitMsgLink = document.querySelector(".latest-commit-msg-link");
    if (latestCommitMsgLink) {
      latestCommitMsgLink.addEventListener("click", () => {
        actions.switchTab("commits");
      });
    }

    return;
  }

  // IF ON FILE VIEWER PANE
  // Back to repo home link
  const backBtn = document.querySelector(".back-to-landing-btn");
  if (backBtn) {
    backBtn.addEventListener("click", () => {
      actions.switchTab("code");
    });
  }

  // Tree sidebar navigation items
  const treeNodes = document.querySelectorAll(".tree-node");
  treeNodes.forEach(node => {
    node.addEventListener("click", () => {
      const type = node.getAttribute("data-type");
      const path = node.getAttribute("data-path");

      if (type === "file") {
        actions.selectFile(path);
      } else {
        actions.toggleFolder(path);
      }
    });
  });

  // Edit file button
  const editBtn = document.getElementById("edit-file-btn");
  if (editBtn) {
    editBtn.addEventListener("click", () => {
      actions.setEditingFile(activeFilePath);
    });
  }

  // Cancel edit button
  const cancelBtn = document.getElementById("cancel-edit-btn");
  if (cancelBtn) {
    cancelBtn.addEventListener("click", () => {
      actions.setEditingFile(null);
    });
  }

  // Commit changes button
  const commitBtn = document.getElementById("commit-changes-trigger-btn");
  if (commitBtn) {
    commitBtn.addEventListener("click", () => {
      const textarea = document.getElementById("file-editor-textarea");
      const msgInput = document.getElementById("commit-msg-input");

      const newContent = textarea ? textarea.value : '';
      const commitMsg = (msgInput && msgInput.value) ? msgInput.value : `Update ${activeFilePath.split('/').pop()}`;

      actions.commitFileChanges(repo.id, activeFilePath, newContent, commitMsg);
    });
  }
}

