// ==========================================================================
// PULL REQUEST TRACKER COMPONENT - GITHUB ANTIGRAVITY EDITION
// ==========================================================================

export function renderPullRequestTracker(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return '';

  // 1. DETAIL VIEW OF A SELECTED PR
  if (state.selectedPrId) {
    return renderPrDetails(state, repo, actions);
  }

  // 2. MAIN LIST VIEW
  const openPrs = repo.pullRequests ? repo.pullRequests.filter(p => p.status === "open") : [];
  const mergedPrs = repo.pullRequests ? repo.pullRequests.filter(p => p.status === "merged") : [];

  const currentTab = state.prsFilterTab || "open";
  const activePrs = currentTab === "open" ? openPrs : mergedPrs;

  // Renders PR alert box (persistent dismissal using localStorage)
  const isAlertDismissed = localStorage.getItem("pr_alert_dismissed") === "true";
  const alertHtml = isAlertDismissed ? '' : `
    <div class="pr-alert-box" id="pr-alert-box" style="border: 1px solid var(--border-color); border-radius: 6px; padding: 1rem 1.25rem; background: var(--bg-card); display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.25rem;">
      <div style="display: flex; flex-direction: column; gap: 0.25rem;">
        <h4 style="font-size: 0.85rem; font-weight: 600; color: var(--text-primary); margin: 0;">Label issues and pull requests for new contributors</h4>
        <p style="font-size: 0.8125rem; color: var(--text-secondary); margin: 0;">
          Now, GitHub will help potential first-time contributors <span style="color: var(--accent-blue); cursor: pointer; text-decoration: underline;">discover issues</span> labeled with <span style="font-size: 0.75rem; padding: 1px 6px; border-radius: 10px; background: rgba(188, 140, 255, 0.15); border: 1px solid rgba(188, 140, 255, 0.3); color: var(--accent-purple); font-weight: 500;">good first issue</span>
        </p>
      </div>
      <button id="dismiss-pr-alert-btn" style="background: transparent; border: none; color: var(--text-link); font-size: 0.8125rem; cursor: pointer; font-weight: 500; padding: 4px 8px;">Dismiss</button>
    </div>
  `;

  // Render list rows
  let prRowsHtml = '';
  if (activePrs.length > 0) {
    prRowsHtml = activePrs.map(pr => {
      const dateStr = formatRelativeTime(pr.createdAt);
      const iconColor = pr.status === 'merged' ? 'var(--accent-purple)' : 'var(--accent-green)';
      const commentsCount = pr.comments ? pr.comments.length : 0;

      return `
        <div class="issue-row pr-row clickable-pr-item" data-id="${pr.id}" style="display: flex; align-items: flex-start; padding: 10px 16px; border-bottom: 1px solid var(--border-color); cursor: pointer; transition: background-color 0.2s;">
          <div style="color: ${iconColor}; margin-right: 0.5rem; margin-top: 0.15rem; display: flex;">
            <i data-lucide="git-pull-request" style="width: 16px; height: 16px;"></i>
          </div>

          <div style="flex-grow: 1;">
            <div style="display: flex; align-items: center; gap: 0.35rem; margin-bottom: 0.15rem;">
              <span style="font-size: 0.875rem; font-weight: 600; color: var(--text-primary);">${pr.title}</span>
            </div>
            <div style="font-size: 0.75rem; color: var(--text-secondary);">
              #${pr.id} opened ${dateStr} by ${pr.author} &middot; main &larr; patch-${pr.id}
            </div>
          </div>

          ${commentsCount > 0 ? `
            <div style="display: flex; align-items: center; gap: 0.15rem; font-size: 0.75rem; color: var(--text-secondary);">
              <i data-lucide="message-square" style="width: 14px; height: 14px;"></i>
              <span>${commentsCount}</span>
            </div>
          ` : ''}
        </div>
      `;
    }).join('');
  }

  // Renders the main PR listing pane
  return `
    <div class="repo-tab-content" style="padding: 1.5rem 0; font-family: var(--font-sans);">
      <!-- Alert bar -->
      ${alertHtml}

      <!-- Search & filters bar -->
      <div style="display: flex; justify-content: space-between; align-items: center; gap: 0.75rem; margin-bottom: 1rem; flex-wrap: wrap;">
        <div style="display: flex; align-items: center; border: 1px solid var(--border-color); background: var(--bg-primary); border-radius: 6px; overflow: hidden; flex-grow: 1; max-width: 600px; height: 32px; position: relative;">
          <button style="background: var(--bg-tertiary); border: none; border-right: 1px solid var(--border-color); color: var(--text-primary); padding: 0 12px; font-size: 0.8125rem; cursor: pointer; display: flex; align-items: center; gap: 0.25rem; height: 100%; font-weight: 500;">
            <span>Filters</span>
            <i data-lucide="chevron-down" style="width: 12px; height: 12px; color: var(--text-secondary);"></i>
          </button>
          <div style="display: flex; align-items: center; padding-left: 32px; flex-grow: 1; height: 100%;">
            <i data-lucide="search" style="width: 14px; height: 14px; color: var(--text-muted); position: absolute; left: 12px; pointer-events: none;"></i>
            <input 
              type="text" 
              id="pr-search-input" 
              value="is:pr is:${currentTab}" 
              style="width: 100%; border: none; background: transparent; color: var(--text-primary); font-size: 0.8125rem; outline: none; height: 100%;" 
            />
          </div>
        </div>

        <div style="display: flex; gap: 0.5rem; align-items: center;">
          <button class="btn btn-sm" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 6px 12px; font-size: 0.75rem; color: var(--text-primary); cursor: pointer; display: flex; align-items: center; gap: 0.35rem; font-weight: 500;">
            <i data-lucide="tag" style="width: 14px; height: 14px; color: var(--text-secondary);"></i>
            <span>Labels</span>
            <span style="background: rgba(255,255,255,0.08); padding: 1px 5px; border-radius: 10px; font-size: 0.7rem; color: var(--text-secondary);">9</span>
          </button>
          <button class="btn btn-sm" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 6px 12px; font-size: 0.75rem; color: var(--text-primary); cursor: pointer; display: flex; align-items: center; gap: 0.35rem; font-weight: 500;">
            <i data-lucide="milestone" style="width: 14px; height: 14px; color: var(--text-secondary);"></i>
            <span>Milestones</span>
            <span style="background: rgba(255,255,255,0.08); padding: 1px 5px; border-radius: 10px; font-size: 0.7rem; color: var(--text-secondary);">0</span>
          </button>

          <button class="btn btn-sm" id="new-pr-btn" style="background: var(--accent-green); border: 1px solid rgba(240,246,252,0.1); border-radius: 6px; padding: 6px 12px; font-size: 0.75rem; color: #fff; cursor: pointer; font-weight: 600; transition: background-color 0.2s;">
            New pull request
          </button>
        </div>
      </div>

      <!-- PR container pane -->
      <div style="border: 1px solid var(--border-color); border-radius: 6px; overflow: hidden; background: var(--bg-card);">
        <!-- Table List Header -->
        <div style="padding: 10px 16px; border-bottom: 1px solid var(--border-color); background-color: var(--bg-tertiary); display: flex; justify-content: space-between; align-items: center;">
          <div style="display: flex; gap: 1rem; font-size: 0.8125rem;">
            <span id="prs-tab-open" style="cursor: pointer; display: flex; align-items: center; gap: 0.25rem; font-weight: ${currentTab === 'open' ? '600' : '400'}; color: ${currentTab === 'open' ? 'var(--text-primary)' : 'var(--text-secondary)'};">
              <i data-lucide="git-pull-request" style="width: 14px; height: 14px; color: var(--accent-green);"></i>
              <span>${openPrs.length} Open</span>
            </span>
            <span id="prs-tab-merged" style="cursor: pointer; display: flex; align-items: center; gap: 0.25rem; font-weight: ${currentTab === 'merged' ? '600' : '400'}; color: ${currentTab === 'merged' ? 'var(--text-primary)' : 'var(--text-secondary)'};">
