}

// --------------------------------------------------------------------------
// PR DETAILS SCREEN RENDERER
// --------------------------------------------------------------------------
function renderPrDetails(state, repo, actions) {
  const pr = repo.pullRequests.find(p => p.id === Number(state.selectedPrId));
  if (!pr) return 'Pull Request not found.';

  const isUserOwner = pr.author === state.user.username;
  const avatar = isUserOwner 
    ? state.user.avatarUrl 
    : "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=60&auto=format&fit=crop&q=80";

  const commentsHtml = [
    {
      author: pr.author,
      isOwner: isUserOwner,
      createdAt: pr.createdAt,
      body: pr.description
    },
    ...(pr.comments || [])
  ].map((c, idx) => {
    const formattedDate = formatRelativeTime(c.createdAt);
    const isUser = c.author === state.user.username;
    const authorAvatar = isUser ? state.user.avatarUrl : "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=60&auto=format&fit=crop&q=80";

    return `
      <div class="comment-item" style="display: flex; gap: 0.75rem; margin-bottom: 1rem;">
        <img src="${authorAvatar}" alt="${c.author}" style="width: 32px; height: 32px; border-radius: 50%; object-fit: cover; border: 1px solid var(--border-color);" />

        <div class="comment-bubble" style="flex-grow: 1; border: 1px solid var(--border-color); border-radius: 8px; background: var(--bg-card); overflow: hidden;">
          <div class="comment-header" style="padding: 8px 12px; border-bottom: 1px solid var(--border-color); background: var(--bg-tertiary); font-size: 0.75rem; color: var(--text-secondary); display: flex; justify-content: space-between;">
            <span><strong>${c.author}</strong> commented ${formattedDate}</span>
            ${idx === 0 ? '<span style="border: 1px solid var(--border-color); padding: 1px 6px; border-radius: 10px; font-size: 0.65rem;">Author</span>' : ''}
          </div>
          <div class="comment-body" style="padding: 12px; font-size: 0.8125rem; color: var(--text-primary); line-height: 1.5; white-space: pre-wrap;">${c.body}</div>
        </div>
      </div>
    `;
  }).join('');

  // Merging action controls panel
  let mergeActionBlockHtml = '';
  if (pr.status === 'open') {
    mergeActionBlockHtml = `
      <div style="border: 1px solid rgba(56, 139, 253, 0.4); border-radius: 8px; background-color: rgba(56, 139, 253, 0.02); padding: 1.25rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; margin-top: 1.5rem;">
        <div style="display: flex; gap: 0.75rem; align-items: flex-start;">
          <div style="background-color: var(--accent-green-bg); color: var(--accent-green); padding: 0.5rem; border-radius: 50%; display: flex;">
            <i data-lucide="git-merge" style="width: 20px; height: 20px;"></i>
          </div>
          <div>
            <h4 style="font-size: 0.875rem; font-weight: 700; color: var(--text-primary); margin: 0 0 0.15rem 0;">This pull request is ready to merge</h4>
            <p style="font-size: 0.75rem; color: var(--text-secondary); margin: 0;">No conflicts detected. Merging will commit the changes into the main branch.</p>
          </div>
        </div>

        <button class="btn btn-primary" id="merge-pr-action-btn" style="background-color: var(--accent-green); border: 1px solid rgba(240,246,252,0.1); border-radius: 6px; padding: 6px 16px; font-size: 0.75rem; color: #fff; font-weight: 600; display: flex; align-items: center; gap: 0.25rem; cursor: pointer;">
          <i data-lucide="git-merge" style="width: 14px; height: 14px;"></i>
          <span>Merge Pull Request</span>
        </button>
      </div>
    `;
  } else if (pr.status === 'merged') {
    mergeActionBlockHtml = `
      <div style="border: 1px solid rgba(188, 140, 255, 0.4); border-radius: 8px; background-color: rgba(188, 140, 255, 0.02); padding: 1.25rem; display: flex; align-items: center; gap: 0.75rem; margin-top: 1.5rem;">
        <div style="background-color: var(--accent-purple-bg); color: var(--accent-purple); padding: 0.5rem; border-radius: 50%; display: flex;">
          <i data-lucide="git-check" style="width: 20px; height: 20px;"></i>
        </div>
        <div>
          <h4 style="font-size: 0.875rem; font-weight: 700; color: var(--accent-purple); margin: 0 0 0.15rem 0;">Pull request successfully merged</h4>
          <p style="font-size: 0.75rem; color: var(--text-secondary); margin: 0;">Changes have been merged into main. The branch can be safely deleted.</p>
        </div>
      </div>
    `;
  }

  const ageStr = formatRelativeTime(pr.createdAt);
  const statusColor = pr.status === 'merged' ? 'var(--accent-purple)' : 'var(--accent-green)';
  const statusLabel = pr.status === 'open' ? 'Open' : 'Merged';
  const statusIcon = pr.status === 'open' ? 'git-pull-request' : 'git-merge';

  return `
    <div class="repo-tab-content" style="padding: 1.5rem 0; font-family: var(--font-sans);">
      <!-- Back button -->
      <button class="btn" id="pr-back-btn" style="background: var(--bg-tertiary); border: 1px solid var(--border-color); border-radius: 6px; padding: 6px 12px; font-size: 0.75rem; color: var(--text-primary); cursor: pointer; display: flex; align-items: center; gap: 0.25rem; margin-bottom: 1.25rem;">
        <i data-lucide="arrow-left" style="width: 14px; height: 14px;"></i>
        <span>Back to Pull Requests</span>
      </button>

      <!-- Title banner -->
      <div style="border-bottom: 1px solid var(--border-color); padding-bottom: 1.25rem; margin-bottom: 1.5rem;">
        <h2 style="font-size: 1.5rem; font-weight: 400; color: var(--text-primary); display: flex; align-items: center; gap: 0.5rem; margin: 0 0 0.5rem 0;">
          <span style="font-weight: 600;">${pr.title}</span>
          <span style="color: var(--text-muted); font-weight: 300;">#${pr.id}</span>
        </h2>

        <div style="display: flex; align-items: center; gap: 0.5rem; font-size: 0.8125rem; color: var(--text-secondary); flex-wrap: wrap;">
          <span style="background-color: ${statusColor}; color: #fff; padding: 3px 10px; border-radius: 12px; font-weight: 600; display: flex; align-items: center; gap: 0.25rem;">
            <i data-lucide="${statusIcon}" style="width: 12px; height: 12px;"></i>
            <span>${statusLabel}</span>
          </span>
          <span>
            <strong>${pr.author}</strong> wants to merge commits into <span style="font-family: var(--font-mono); background: var(--bg-tertiary); padding: 1px 4px; border-radius: 4px; font-size: 0.75rem; border: 1px solid var(--border-color); color: var(--accent-blue);">main</span> from <span style="font-family: var(--font-mono); background: var(--bg-tertiary); padding: 1px 4px; border-radius: 4px; font-size: 0.75rem; border: 1px solid var(--border-color); color: var(--accent-orange);">patch-${pr.id}</span> &middot; opened ${ageStr}
          </span>
        </div>
      </div>

      <!-- Thread + Merging panel grid -->
      <div style="max-width: 800px; display: flex; flex-direction: column;">
        <div style="display: flex; flex-direction: column;">
          ${commentsHtml}
        </div>

        ${mergeActionBlockHtml}
      </div>
    </div>
  `;
}

// --------------------------------------------------------------------------
// HELPER METHODS
// --------------------------------------------------------------------------
function formatRelativeTime(dateString) {
  if (!dateString) return "8 months ago";
  const date = new Date(dateString);
  const now = new Date();
  const diffMs = now - date;

  const diffSecs = Math.floor(diffMs / 1000);
  const diffMins = Math.floor(diffSecs / 60);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffSecs < 60) return "just now";
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 30) return `${diffDays}d ago`;

  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

// --------------------------------------------------------------------------
// ATTACH LISTENERS
// --------------------------------------------------------------------------
export function attachPullRequestTrackerListeners(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return;

  // 1. DETAIL SCREEN LISTENERS
  if (state.selectedPrId) {
    const backBtn = document.getElementById("pr-back-btn");
    if (backBtn) {
      backBtn.addEventListener("click", () => {
        actions.selectPr(null);
      });
    }

    const mergeBtn = document.getElementById("merge-pr-action-btn");
    if (mergeBtn) {
      mergeBtn.addEventListener("click", () => {
        actions.mergePullRequest(repo.id, state.selectedPrId);
      });
    }
    return;
  }

  // 2. MAIN LIST LISTENERS
  // Alert dismiss button click
  const dismissBtn = document.getElementById("dismiss-pr-alert-btn");
  if (dismissBtn) {
    dismissBtn.addEventListener("click", () => {
      localStorage.setItem("pr_alert_dismissed", "true");
      const alertBox = document.getElementById("pr-alert-box");
      if (alertBox) alertBox.style.display = "none";
    });
  }

  // Tabs filters (Open / Merged)
  const openTab = document.getElementById("prs-tab-open");
  if (openTab) {
    openTab.addEventListener("click", () => {
      actions.setPrsFilterTab("open");
    });
  }

  const mergedTab = document.getElementById("prs-tab-merged");
  if (mergedTab) {
    mergedTab.addEventListener("click", () => {
      actions.setPrsFilterTab("merged");
    });
  }

  // New pull request button triggers modal
  const newPrBtn = document.getElementById("new-pr-btn");
  if (newPrBtn) {
    newPrBtn.addEventListener("click", () => {
      actions.toggleCreatePrModal(true);
    });
  }

  const firstPrLink = document.getElementById("create-first-pr-link");
  if (firstPrLink) {
    firstPrLink.addEventListener("click", () => {
      actions.toggleCreatePrModal(true);
    });
  }

  // Clicking PR list row opens details view
  const prItems = document.querySelectorAll(".clickable-pr-item");
  prItems.forEach(item => {
    item.addEventListener("click", () => {
      const prId = item.getAttribute("data-id");
      actions.selectPr(prId);
    });
  });
}

